/-- AllPmOne is preserved under appending. -/
lemma AllPmOne_appendFn {n m : Nat} {a : Fin n → Int} {b : Fin m → Int}
    (ha : AllPmOne a) (hb : AllPmOne b) : AllPmOne (appendFn a b)

/-- Alternation: entry at position `i` gets factor `(-1)^i`. -/
def Turyn.altSeqFn {n : Nat} (a : Fin n → Int) : Fin n → Int :=
  fun i => (if i.1 % 2 = 0 then (1 : Int) else -1) * a i

/-- Reversal: entry at position `i` becomes the entry at position `n - 1 - i`. -/
def reverseFn {n : Nat} (a : Fin n → Int) : Fin n → Int :=
  fun i => a ⟨n - 1 - i.1, by have := i.2; omega⟩

/-- Equivalence is the reflexive-transitive closure of elementary transformations. -/
def Equivalent (n : Nat) (S T : TurynType n) : Prop :=
  Relation.ReflTransGen (Elementary n) S T

/-- A single elementary step implies equivalence. -/
lemma Elementary.toEquivalent {n : Nat} {S T : TurynType n}
    (h : Elementary n S T) : Equivalent n S T

/-- Propositional version: every entry is `0`, `1`, or `−1`. -/
def AllSignOne {n : Nat} (a : Fin n → Int) : Prop :=
  ∀ i : Fin n, a i = 0 ∨ a i = 1 ∨ a i = -1

/-- Look up `a : Fin n → Int` at 0-indexed `Nat` position `i`, returning `0`
if out of range.  Defined here (instead of inside `namespace Turyn`)
because `aperiodicAutocorr` uses it in the sum body. -/
def lookupNat {n : Nat} (a : Fin n → Int) (i : Nat) : Int :=
  if h : i < n then a ⟨i, h⟩ else 0

def aperiodicAutocorr {n : Nat} (a : Fin n → Int) (s : Nat) : Int :=
  if s ≥ n then 0
  else ∑ i ∈ range (n - s), lookupNat a i * lookupNat a (i + s)

/-- Total autocorrelation: sum of N_a(s) for s = 1, …, k−1. -/
def totalAutocorr {k : Nat} (a : Fin k → Int) : Int :=
  ∑ i ∈ range (k - 1), aperiodicAutocorr a (i + 1)

/-- Weighted total autocorrelation for a TT quadruple. -/
def weightedTotalAutocorr {n : Nat} (x y z : Fin n → Int) (w : Fin (n - 1) → Int) : Int :=
  ∑ i ∈ range (n - 1), combinedAutocorr x y z w (i + 1)

/-- The constructive pipeline produces a Hadamard matrix of order `68` from TT(6). -/
def tt6_hadamard : IntMat 68 :=
  ofIsTurynTypeMatrix tt6_valid

/-- Typed transpose-twisted circulant block, corresponding to `Aᵀ R = R A`. -/
def trCirculant {n : Nat} (x : IntVec n) : IntMat n :=
  (circulant x)ᵀ * reversalMatrix n

/-- The typed GS matrix. -/
def gsMatrix {n : Nat} (G : GSData n) : IntMat (4 * n) :=
  gsMatrixEntry G

/-- Matrix-theoretic orthogonality target for the typed GS matrix. -/
def GSTarget {n : Nat} (G : GSData n) : Prop :=
  gsMatrix G * (gsMatrix G)ᵀ = (4 * n : Int) • (1 : IntMat (4 * n))

/-- Block-matrix GS orthogonality target. -/
def GSBlockTarget {n : Nat} (G : GSData n) : Prop :=
  gsBlockMatrix G * (gsBlockMatrix G)ᵀ = (4 * n : Int) • (1 : GSBlockMat n)

/-- First GS combination: A + B + C + D. -/
def tseqCombine1 {m : Nat} (T : TSequence m) : Fin m → Int :=
  fun i => T.a.data i + T.b.data i + T.c.data i + T.d.data i

/-- Second GS combination: A + B - C - D. -/
def tseqCombine2 {m : Nat} (T : TSequence m) : Fin m → Int :=
  fun i => T.a.data i + T.b.data i - T.c.data i - T.d.data i

/-- Third GS combination: A - B + C - D. -/
def tseqCombine3 {m : Nat} (T : TSequence m) : Fin m → Int :=
  fun i => T.a.data i - T.b.data i + T.c.data i - T.d.data i

/-- Fourth GS combination: A - B - C + D. -/
def tseqCombine4 {m : Nat} (T : TSequence m) : Fin m → Int :=
  fun i => T.a.data i - T.b.data i - T.c.data i + T.d.data i

/-- The typed GS matrix attached to a T-sequence. -/
def typedGsMatrixOfTSequence {m : Nat} (T : TSequence m) : IntMat (4 * m) :=
  gsMatrix (gsDataOfTSequence T).toGSData

/-- Entrywise `±1` condition for typed vectors. -/
def IsPmOneVec {n : Nat} (x : IntVec n) : Prop :=
  ∀ i, x i = 1 ∨ x i = -1

/-- Periodic autocorrelation on a typed vector. -/
def periodicAutocorr {n : Nat} (x : IntVec n) (s : Fin n) : Int :=
  ∑ i : Fin n, x i * x (i + s)

/-- The standard circulant matrix attached to a typed vector. -/
def circulant {n : Nat} (x : IntVec n) : IntMat n :=
  fun i j => x (j - i)

/-- The reversal matrix `R`. -/
def reversalMatrix (n : Nat) : IntMat n :=
  fun i j => if j = revFin i then 1 else 0

/-- Step 2a: Z in positions `[0, n)`, zero elsewhere. -/
def step2a {n : Nat} (T : TurynType n) : Fin (3 * n - 1) → Int :=
  fun i => if h : i.1 < n then T.Z.data ⟨i.1, h⟩ else 0

/-- Element-wise half-sum. -/
def halfSumFn {n : Nat} (x y : Fin n → Int) : Fin n → Int :=
  fun i => (x i + y i) / 2

/-- Element-wise half-difference. -/
def halfDiffFn {n : Nat} (x y : Fin n → Int) : Fin n → Int :=
  fun i => (x i - y i) / 2

/-- Convert a sign character into the corresponding `±1` value. -/
def charToPm? (c : Char) : Option Int :=
  if c = '+' then some 1
  else if c = '-' then some (-1)
  else none

/-- Boolean check that every entry of a list is ±1. -/
def allPmOne (a : List Int) : Bool :=
  a.all fun v => v == 1 || v == -1

/-- Boolean check that every entry of a list is `0`, `1`, or `−1`. -/
def allSignOne (a : List Int) : Bool :=
  a.all fun v => v == 0 || v == 1 || v == -1

/-- Function view of a `List Int` as a `Fin n → Int` (default `0` out of range). -/
def listToFin (l : List Int) (n : Nat) : Fin n → Int :=
  fun i => l.getD i.1 0

/-- Every `±1` sequence is also a `{0, ±1}` sequence. -/
def PmSeq.toSign {n : Nat} (s : PmSeq n) : SignSeq n :=
  { data := s.data
    sign := fun i => Or.inr (s.pm i) }

/-- Convert an `IsTurynType` certificate into the bundled `TurynType`. -/
def IsTurynType.toTyped {n : Nat} {X Y Z : PmSeq n} {W : PmSeq (n - 1)}
    (h : IsTurynType X Y Z W) : TurynType n :=
  { X := X, Y := Y, Z := Z, W := W, vanishing := h }

/-- Under `Canonical1`, the first entry of `u` is 1. -/
lemma uAt_one_of_canonical1_head {n : Nat} {S : TurynType n}
    (hc : Canonical1 n S) : uAt S 1 = 1

/-- Under `Canonical1`, the last entry of `u` is 1. -/
lemma uAt_one_of_canonical1_tail {n : Nat} {S : TurynType n}
    (_hn : 1 ≤ n) (hc : Canonical1 n S) : uAt S n = 1
